import hashlib, json

_cache: dict[str, str] = {}

def _key(model: str, prompt: str, params: dict) -> str:
    norm = " ".join(prompt.split()).lower()
    raw = json.dumps({"m": model, "p": norm, "k": params}, sort_keys=True)
    return hashlib.sha256(raw.encode()).hexdigest()

def cached_complete(client, model: str, prompt: str, **params) -> str:
    k = _key(model, prompt, params)
    if k in _cache:
        return _cache[k]              # no tokens, no latency
    text = client.complete(model=model, prompt=prompt, **params)
    _cache[k] = text
    return text

