from pydantic import BaseModel, Field, ValidationError
from typing import Literal

class TicketTriage(BaseModel):
    category: Literal["billing", "bug", "feature", "other"]
    severity: int = Field(ge=1, le=4)
    summary: str = Field(max_length=200)
    needs_human: bool

MODEL = "provider-model-2024-06-01"   # pinned, not a floating alias

def triage(client, ticket: str, retries: int = 2) -> TicketTriage:
    prompt = ("Classify the support ticket. Reply with JSON matching "
              f"this schema: {TicketTriage.model_json_schema()}\n"
              f"<ticket>{ticket}</ticket>")
    for attempt in range(retries + 1):
        raw = client.complete(model=MODEL, prompt=prompt)
        try:
            return TicketTriage.model_validate_json(raw)
        except ValidationError as e:
            prompt += f"\nYour last reply was invalid: {e.errors()[0]['msg']}"
    raise RuntimeError("no valid structured output")
